package main

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"time"

	"stackd/compute/docker"
	"stackd/compute/network"
)

func main() {
	client, err := docker.New(context.Background(), docker.Config{})
	if err != nil {
		panic(err)
	}
	defer client.Close()
	bridges, err := network.NewBridges(client)
	if err != nil {
		panic(err)
	}
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		var input struct {
			Operation string
			Spec      network.Specification
		}
		var output struct {
			Bridge   network.Bridge
			Attached bool
			Error    string
		}
		err := json.Unmarshal(scanner.Bytes(), &input)
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		if err == nil {
			switch input.Operation {
			case "prepare":
				err = bridges.WithBridge(ctx, input.Spec, func(bridge network.Bridge) error {
					output.Attached = true
					output.Bridge = bridge
					return nil
				})
			case "release":
				err = bridges.Release(ctx, input.Spec.NetworkID)
			default:
				err = fmt.Errorf("unknown proof operation")
			}
		}
		cancel()
		if err != nil {
			output.Error = err.Error()
		}
		if err := json.NewEncoder(os.Stdout).Encode(output); err != nil {
			panic(err)
		}
	}
	if err := scanner.Err(); err != nil {
		panic(err)
	}
}
